            signed_at=row.day("signed_at", required=True),
        )
        if row.ok:
            contracts.append(c)

    works: list[Work] = []
    for row in _read_rows(base / "works.csv", WORK_COLUMNS, errors):
        w = Work(
            work_id=row.text("work_id"),
            contract_id=row.text("contract_id"),
            title=row.text("title"),
            price=row.money("price"),
            status=row.choice("status", WORK_STATUSES),
            completed_at=row.day("completed_at"),
            cancelled_at=row.day("cancelled_at"),
        )
        # Статус и дата должны быть согласованы: по дате мы потом
        # восстанавливаем, что было на заданный день.
        if row.ok and w.status == "done" and w.completed_at is None:
            errors.append(f"works.csv: работа {w.work_id}: статус done, но нет completed_at")
            row.ok = False
        if row.ok and w.status == "cancelled" and w.cancelled_at is None:
            errors.append(f"works.csv: работа {w.work_id}: статус cancelled, но нет cancelled_at")
            row.ok = False
        if row.ok:
            works.append(w)

    payments: list[Payment] = []
    for row in _read_rows(base / "payments.csv", PAYMENT_COLUMNS, errors):
        p = Payment(
            payment_id=row.text("payment_id"),
            contract_id=row.text("contract_id"),
            work_id=row.text("work_id", required=False) or None,
            purpose=row.text("purpose", required=False),
            amount=row.money("amount"),
            status=row.choice("status", PAYMENT_STATUSES),
            created_at=row.day("created_at", required=True),
            paid_at=row.day("paid_at"),
            refunded_at=row.day("refunded_at"),
        )
        if row.ok:
            problem = _payment_dates_problem(p)
            if problem:
                errors.append(f"payments.csv: платёж {p.payment_id}: {problem}")
            else:
                payments.append(p)

    _unique(contracts, lambda c: c.contract_id, "contracts.csv", errors)
    _unique(works, lambda w: w.work_id, "works.csv", errors)
    _unique(payments, lambda p: p.payment_id, "payments.csv", errors)

    contract_ids = {c.contract_id for c in contracts}
    work_contract = {w.work_id: w.contract_id for w in works}
    for w in works:
        if w.contract_id not in contract_ids:
            errors.append(f"works.csv: работа {w.work_id}: неизвестный договор {w.contract_id}")
    for p in payments:
        if p.contract_id not in contract_ids:
            errors.append(f"payments.csv: платёж {p.payment_id}: неизвестный договор {p.contract_id}")
        if p.work_id is not None:
            if p.work_id not in work_contract:
                errors.append(f"payments.csv: платёж {p.payment_id}: неизвестная работа {p.work_id}")
            elif work_contract[p.work_id] != p.contract_id:
                # Молча "починить" нельзя: непонятно, ошибка в договоре или в работе.
                errors.append(
                    f"payments.csv: платёж {p.payment_id}: работа {p.work_id} относится к договору "
                    f"{work_contract[p.work_id]}, а платёж указан по договору {p.contract_id}"
                )

    if errors:
        raise DataError(errors)
    return Dataset(tuple(contracts), tuple(works), tuple(payments))


def _payment_dates_problem(p: Payment) -> Optional[str]:
    """Статус платежа должен соответствовать заполненным датам."""
    if p.status == "queued" and p.paid_at is not None:
        return "статус queued, но указана дата оплаты paid_at"
    if p.status == "paid" and p.paid_at is None:
        return "статус paid, но нет paid_at"
    if p.status == "refunded":
        if p.paid_at is None or p.refunded_at is None:
            return "статус refunded, но нет paid_at или refunded_at"
        if p.refunded_at < p.paid_at:
            return "возврат раньше оплаты (refunded_at < paid_at)"
    return None

