"""Модели данных: сырые записи из выгрузки и результат расчёта."""
from __future__ import annotations

from dataclasses import dataclass, field
from datetime import date
from decimal import Decimal
from enum import Enum

from .money import ZERO


class WorkStatus(str, Enum):
    PLANNED = "planned"
    DONE = "done"
    CANCELLED = "cancelled"


class PaymentStatus(str, Enum):
    PAID = "paid"
    QUEUED = "queued"
    REFUNDED = "refunded"


# --------------------------------------------------------------------------
# Входные данные (как в выгрузке, без интерпретации)
# --------------------------------------------------------------------------

@dataclass(frozen=True)
class Contract:
    id: str
    contractor: str
    amount: Decimal
    signed_at: date


@dataclass(frozen=True)
class Work:
    id: str
    contract_id: str
    title: str
    price: Decimal
    status: WorkStatus
    completed_at: date | None
    cancelled_at: date | None


@dataclass(frozen=True)
class Payment:
    id: str
    contract_id: str
    work_id: str | None  # None -- платёж по договору без привязки к работе
    purpose: str
    amount: Decimal
    status: PaymentStatus
    created_at: date
    paid_at: date | None
    refunded_at: date | None


@dataclass(frozen=True)
class Dataset:
    contracts: list[Contract]
    works: list[Work]
    payments: list[Payment]


# --------------------------------------------------------------------------
# Результат расчёта
# --------------------------------------------------------------------------

@dataclass(frozen=True)
class Issue:
    """Замечание к договору: то, что бухгалтеру нужно проверить глазами."""
    code: str
    message: str


@dataclass(frozen=True)
class WorkLine:
    work: Work
    state: WorkStatus      # статус НА ДАТУ отчёта (может отличаться от status в выгрузке)
    payable: Decimal       # сколько за работу надо заплатить: price, а для отменённой 0
    paid_linked: Decimal   # платежи, явно привязанные к этой работе
    paid_allocated: Decimal  # доля «безадресных» платежей по договору, отнесённая сюда

    @property
    def paid(self) -> Decimal:
        return self.paid_linked + self.paid_allocated

    @property
    def remaining(self) -> Decimal:
        return max(self.payable - self.paid, ZERO)

    @property
    def overpaid(self) -> Decimal:
        return max(self.paid - self.payable, ZERO)


@dataclass(frozen=True)
class ContractReport:
    contract: Contract
    lines: list[WorkLine]
    unallocated: Decimal   # выплачено сверх стоимости всех работ: не на что отнести
    queued: Decimal        # в очереди на оплату на дату отчёта (деньги ещё не ушли)
    issues: list[Issue] = field(default_factory=list)

    @property
    def works_total(self) -> Decimal:
        """Цена работ без отменённых."""
        return sum((l.payable for l in self.lines), ZERO)

    @property
    def cancelled_total(self) -> Decimal:
        return sum((l.work.price for l in self.lines if l.state is WorkStatus.CANCELLED), ZERO)

    @property
    def paid(self) -> Decimal:
        """Реально выплачено на дату, с учётом возвратов."""
        return sum((l.paid for l in self.lines), ZERO) + self.unallocated

    @property
    def remaining(self) -> Decimal:
        return sum((l.remaining for l in self.lines), ZERO)

    @property
    def due_accepted(self) -> Decimal:
        """Остаток по уже принятым работам -- то, что подрядчик вправе требовать сейчас."""
        return sum((l.remaining for l in self.lines if l.state is WorkStatus.DONE), ZERO)

    @property
    def overpaid(self) -> Decimal:
        return sum((l.overpaid for l in self.lines), ZERO) + self.unallocated


@dataclass(frozen=True)
class Report:
    as_of: date
    contracts: list[ContractReport]
    skipped_contracts: list[Contract]  # подписаны позже даты отчёта

