"""Чтение и строгая валидация CSV из data/.

Принцип: структурные ошибки (битая сумма, дата, несуществующая ссылка) -- это
DataError с указанием файла и строки; расчёт на таких данных не запускается,
потому что молча «угаданные» деньги хуже, чем остановка. Смысловые странности
(переплата, расхождение суммы договора) -- не ошибки загрузки, их ловит calc.
"""
from __future__ import annotations

import csv
from datetime import date
from pathlib import Path
from typing import Callable, TypeVar

from .models import (
    Contract, Dataset, Payment, PaymentStatus, Work, WorkStatus,
)
from .money import ZERO, parse_money

E = TypeVar("E")


class DataError(Exception):
    """Данные в data/ некорректны."""


def _read_rows(path: Path, required: tuple[str, ...]) -> list[tuple[int, dict[str, str]]]:
    if not path.is_file():
        raise DataError(f"{path}: файл не найден")
    # utf-8-sig: Excel любит дописывать BOM, без него первая колонка «ломается».
    with path.open(encoding="utf-8-sig", newline="") as fh:
        reader = csv.DictReader(fh)
        missing = [c for c in required if c not in (reader.fieldnames or [])]
        if missing:
            raise DataError(f"{path}: нет колонок {', '.join(missing)}")
        rows = []
        for row in reader:
            # DictReader не ругается на короткие/длинные строки, а заполняет
            # None / складывает хвост под ключ None -- ловим это явно.
            if None in row or any(v is None for v in row.values()):
                raise DataError(f"{path}:{reader.line_num}: число колонок не совпадает с заголовком")
            rows.append((reader.line_num, {k: v.strip() for k, v in row.items()}))
        return rows


def _wrap(path: Path, line: int, fn: Callable[[], E]) -> E:
    try:
        return fn()
    except (ValueError, KeyError) as exc:
        raise DataError(f"{path}:{line}: {exc}") from exc


def _date(value: str, field: str) -> date:
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError(f"колонка {field}: некорректная дата {value!r} (ожидается ГГГГ-ММ-ДД)") from None


def _opt_date(value: str, field: str) -> date | None:
    return _date(value, field) if value else None


def _enum(enum_cls: type[E], value: str, field: str) -> E:
    try:
        return enum_cls(value)  # type: ignore[call-arg]
    except ValueError:
        allowed = ", ".join(m.value for m in enum_cls)  # type: ignore[attr-defined]
        raise ValueError(f"колонка {field}: неизвестный статус {value!r} (допустимо: {allowed})") from None


def _required(row: dict[str, str], field: str) -> str:
    if not row[field]:
        raise ValueError(f"колонка {field}: значение обязательно")
    return row[field]


def _unique(path: Path, seen: set[str], line: int, key: str) -> None:
    if key in seen:
        raise DataError(f"{path}:{line}: повторяющийся идентификатор {key!r}")
    seen.add(key)


def load_dataset(data_dir: Path) -> Dataset:
    contracts = _load_contracts(data_dir / "contracts.csv")
    contract_ids = {c.id for c in contracts}
    works = _load_works(data_dir / "works.csv", contract_ids)
    payments = _load_payments(data_dir / "payments.csv", contract_ids, works)
    return Dataset(contracts, works, payments)


def _load_contracts(path: Path) -> list[Contract]:
    out, seen = [], set()
    for line, row in _read_rows(path, ("contract_id", "contractor", "amount", "signed_at")):
        def build(row=row) -> Contract:
            return Contract(
                id=_required(row, "contract_id"),
                contractor=row["contractor"],
                amount=parse_money(row["amount"]),
                signed_at=_date(row["signed_at"], "signed_at"),
            )
        c = _wrap(path, line, build)
        _unique(path, seen, line, c.id)
        out.append(c)
    return out


def _load_works(path: Path, contract_ids: set[str]) -> list[Work]:
    out, seen = [], set()
    cols = ("work_id", "contract_id", "title", "price", "status", "completed_at", "cancelled_at")
    for line, row in _read_rows(path, cols):
        def build(row=row) -> Work:
            status = _enum(WorkStatus, row["status"], "status")
            completed = _opt_date(row["completed_at"], "completed_at")
            cancelled = _opt_date(row["cancelled_at"], "cancelled_at")
            # Дата, нужная для расчёта «на дату», обязана быть: иначе мы не
            # узнаем, была ли работа принята/отменена к дате отчёта.
            if status is WorkStatus.DONE and completed is None:
                raise ValueError("status=done, но completed_at пуст")
            if status is WorkStatus.CANCELLED and cancelled is None:
                raise ValueError("status=cancelled, но cancelled_at пуст")
            return Work(
                id=_required(row, "work_id"),
                contract_id=_required(row, "contract_id"),
                title=row["title"],
                price=parse_money(row["price"]),
                status=status,
                completed_at=completed,
                cancelled_at=cancelled,
            )
        w = _wrap(path, line, build)
        _unique(path, seen, line, w.id)
        if w.contract_id not in contract_ids:
            raise DataError(f"{path}:{line}: работа {w.id} ссылается на несуществующий договор {w.contract_id}")
        out.append(w)
    return out


def _load_payments(path: Path, contract_ids: set[str], works: list[Work]) -> list[Payment]:
    work_contract = {w.id: w.contract_id for w in works}
    out, seen = [], set()
    cols = ("payment_id", "contract_id", "work_id", "purpose", "amount", "status",
            "created_at", "paid_at", "refunded_at")
    for line, row in _read_rows(path, cols):
        def build(row=row) -> Payment:
            status = _enum(PaymentStatus, row["status"], "status")
            paid = _opt_date(row["paid_at"], "paid_at")
            refunded = _opt_date(row["refunded_at"], "refunded_at")
            if status is PaymentStatus.PAID and paid is None:
                raise ValueError("status=paid, но paid_at пуст")
            if status is PaymentStatus.REFUNDED:
                if paid is None or refunded is None:
                    raise ValueError("status=refunded требует и paid_at, и refunded_at")
                if refunded < paid:
                    raise ValueError("refunded_at раньше paid_at")
            if status is PaymentStatus.QUEUED and paid is not None:
                raise ValueError("status=queued, но paid_at заполнен")
            amount = parse_money(row["amount"])
            if amount <= ZERO:
                raise ValueError("сумма платежа должна быть больше нуля")
            return Payment(
                id=_required(row, "payment_id"),
                contract_id=_required(row, "contract_id"),
                work_id=row["work_id"] or None,
                purpose=row["purpose"],
                amount=amount,
                status=status,
                created_at=_date(row["created_at"], "created_at"),
