"""Командная строка. Коды выхода: 0 -- ок, 1 -- ошибка данных/записи, 2 -- неверные аргументы."""
from __future__ import annotations

import argparse
import sys
from datetime import date, datetime
from pathlib import Path

from .calc import build_report
from .loader import DataError, load_dataset
from .render import RENDERERS


def parse_date(raw: str) -> date:
    """Принимаем и привычное бухгалтерии ДД.ММ.ГГГГ, и ISO (как в самих данных)."""
    for fmt in ("%d.%m.%Y", "%Y-%m-%d"):
        try:
            return datetime.strptime(raw.strip(), fmt).date()
        except ValueError:
            continue
    raise argparse.ArgumentTypeError(f"неверная дата {raw!r}: ожидается ДД.ММ.ГГГГ или ГГГГ-ММ-ДД")


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(
        prog="contract_report",
        description="Отчёт по договорам: сколько выплачено и сколько осталось оплатить по каждой работе.",
    )
    p.add_argument("--data", type=Path, default=Path("data"), help="папка с CSV (по умолчанию ./data)")
    p.add_argument("--date", type=parse_date, default=None,
                   help="дата отчёта, ДД.ММ.ГГГГ или ГГГГ-ММ-ДД (по умолчанию сегодня)")
    p.add_argument("--format", choices=sorted(RENDERERS), default="table", help="формат вывода")
    p.add_argument("--contract", metavar="ID", help="показать только один договор")
    p.add_argument("--output", "-o", type=Path, help="записать в файл вместо stdout")
    return p


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    as_of = args.date or date.today()
    try:
        report = build_report(load_dataset(args.data), as_of)
        if args.contract:
            known = {r.contract.id for r in report.contracts}
            if args.contract not in known:
                print(f"Ошибка: договор {args.contract!r} не найден на {as_of:%d.%m.%Y} "
                      f"(есть: {', '.join(sorted(known)) or 'нет'})", file=sys.stderr)
                return 1
            report = type(report)(report.as_of,
                                  [r for r in report.contracts if r.contract.id == args.contract], [])
        text = RENDERERS[args.format](report)
    except DataError as exc:
        print(f"Ошибка данных: {exc}", file=sys.stderr)
        return 1

    if args.output:
        # utf-8-sig для CSV: без BOM Excel на Windows показывает кириллицу кракозябрами.
        enc = "utf-8-sig" if args.format == "csv" else "utf-8"
        try:
            args.output.write_text(text, encoding=enc, newline="")
        except OSError as exc:
            print(f"Ошибка записи {args.output}: {exc}", file=sys.stderr)
            return 1
    else:
        sys.stdout.write(text)
    return 0


if __name__ == "__main__":
    sys.exit(main())

