"""Чтение и проверка CSV-файлов из каталога данных.

Принцип: если данные противоречивы, отчёт не строится вовсе. Бухгалтер
не сможет заметить, что цифра посчитана по битой строке, поэтому лучше
получить список ошибок с номерами строк, чем "почти правильный" отчёт.
Все ошибки собираются разом, а не по одной, чтобы их можно было
исправить за один заход.
"""

from __future__ import annotations

import csv
from datetime import date
from decimal import Decimal
from pathlib import Path
from typing import Callable, Optional, TypeVar

from .models import (
    PAYMENT_STATUSES,
    WORK_STATUSES,
    Contract,
    Dataset,
    Payment,
    Work,
)
from .money import parse_money

T = TypeVar("T")

CONTRACT_COLUMNS = ("contract_id", "contractor", "amount", "signed_at")
WORK_COLUMNS = (
    "work_id", "contract_id", "title", "price",
    "status", "completed_at", "cancelled_at",
)
PAYMENT_COLUMNS = (
    "payment_id", "contract_id", "work_id", "purpose", "amount",
    "status", "created_at", "paid_at", "refunded_at",
)


class DataError(Exception):
    """Данные не прошли проверку. ``errors`` - человекочитаемый список."""

    def __init__(self, errors: list[str]):
        super().__init__("\n".join(errors))
        self.errors = errors


class _Row:
    """Обёртка над строкой CSV: достаёт типизированные поля и копит ошибки."""

    def __init__(self, filename: str, line: int, raw: dict[str, str], errors: list[str]):
        self._where = f"{filename}:{line}"
        self._raw = raw
        self._errors = errors
        self.ok = True

    def _fail(self, column: str, message: str) -> None:
        self._errors.append(f"{self._where}: колонка {column}: {message}")
        self.ok = False

    def text(self, column: str, required: bool = True) -> str:
        value = (self._raw.get(column) or "").strip()
        if required and not value:
            self._fail(column, "значение не заполнено")
        return value

    def _convert(self, column: str, required: bool, parse: Callable[[str], T]) -> Optional[T]:
        value = self.text(column, required)
        if not value:
            return None
        try:
            return parse(value)
        except ValueError as exc:
            self._fail(column, str(exc))
            return None

    def money(self, column: str) -> Optional[Decimal]:
        amount = self._convert(column, True, parse_money)
        if amount is not None and amount <= 0:
            self._fail(column, f"сумма должна быть больше нуля: {amount}")
            return None
        return amount

    def day(self, column: str, required: bool = False) -> Optional[date]:
        def parse(value: str) -> date:
            try:
                # Только ISO: fromisoformat в 3.11+ принимает и "20261110",
                # поэтому дополнительно требуем дефисы.
                if len(value) != 10:
                    raise ValueError
                return date.fromisoformat(value)
            except ValueError:
                raise ValueError(f"ожидалась дата ГГГГ-ММ-ДД, получено {value!r}") from None

        return self._convert(column, required, parse)

    def choice(self, column: str, allowed: tuple[str, ...]) -> Optional[str]:
        value = self.text(column)
        if value and value not in allowed:
            self._fail(column, f"недопустимый статус {value!r}, ожидалось одно из {', '.join(allowed)}")
            return None
        return value or None


def _read_rows(path: Path, columns: tuple[str, ...], errors: list[str]) -> list[_Row]:
    if not path.is_file():
        errors.append(f"{path.name}: файл не найден в {path.parent}")
        return []
    # utf-8-sig: выгрузки из Excel нередко приходят с BOM.
    with path.open(newline="", encoding="utf-8-sig") as fh:
        reader = csv.DictReader(fh)
        missing = [c for c in columns if c not in (reader.fieldnames or [])]
        if missing:
            errors.append(f"{path.name}: нет колонок {', '.join(missing)}")
            return []
        # Нумерация с 2: первая строка файла - заголовок.
        return [
            _Row(path.name, number, raw, errors)
            for number, raw in enumerate(reader, start=2)
        ]


def _unique(items: list, key: Callable, filename: str, errors: list[str]) -> None:
    seen: set[str] = set()
    for item in items:
        k = key(item)
        if k in seen:
            errors.append(f"{filename}: повторяется идентификатор {k}")
        seen.add(k)


def load_dataset(data_dir: Path | str) -> Dataset:
    """Прочитать contracts.csv, works.csv, payments.csv и проверить связность."""
    base = Path(data_dir)
    errors: list[str] = []

    contracts: list[Contract] = []
    for row in _read_rows(base / "contracts.csv", CONTRACT_COLUMNS, errors):
        c = Contract(
            contract_id=row.text("contract_id"),
            contractor=row.text("contractor"),
            amount=row.money("amount"),
            signed_at=row.day("signed_at", required=True),
        )
        if row.ok:
            contracts.append(c)

    works: list[Work] = []
    for row in _read_rows(base / "works.csv", WORK_COLUMNS, errors):
        w = Work(
            work_id=row.text("work_id"),
            contract_id=row.text("contract_id"),
            title=row.text("title"),
            price=row.money("price"),
            status=row.choice("status", WORK_STATUSES),
            completed_at=row.day("completed_at"),
            cancelled_at=row.day("cancelled_at"),
        )
        # Статус и дата должны быть согласованы: по дате мы потом
        # восстанавливаем, что было на заданный день.
        if row.ok and w.status == "done" and w.completed_at is None:
            errors.append(f"works.csv: работа {w.work_id}: статус done, но нет completed_at")
            row.ok = False
        if row.ok and w.status == "cancelled" and w.cancelled_at is None:
            errors.append(f"works.csv: работа {w.work_id}: статус cancelled, но нет cancelled_at")
            row.ok = False
        if row.ok:
            works.append(w)

    payments: list[Payment] = []
    for row in _read_rows(base / "payments.csv", PAYMENT_COLUMNS, errors):
        p = Payment(
            payment_id=row.text("payment_id"),
            contract_id=row.text("contract_id"),
            work_id=row.text("work_id", required=False) or None,
            purpose=row.text("purpose", required=False),
            amount=row.money("amount"),
            status=row.choice("status", PAYMENT_STATUSES),
            created_at=row.day("created_at", required=True),
            paid_at=row.day("paid_at"),
            refunded_at=row.day("refunded_at"),
        )
        if row.ok:
            problem = _payment_dates_problem(p)
            if problem:
                errors.append(f"payments.csv: платёж {p.payment_id}: {problem}")
            else:
                payments.append(p)

    _unique(contracts, lambda c: c.contract_id, "contracts.csv", errors)
    _unique(works, lambda w: w.work_id, "works.csv", errors)
    _unique(payments, lambda p: p.payment_id, "payments.csv", errors)

    contract_ids = {c.contract_id for c in contracts}
    work_contract = {w.work_id: w.contract_id for w in works}
    for w in works:
        if w.contract_id not in contract_ids:
            errors.append(f"works.csv: работа {w.work_id}: неизвестный договор {w.contract_id}")
    for p in payments:
        if p.contract_id not in contract_ids:
            errors.append(f"payments.csv: платёж {p.payment_id}: неизвестный договор {p.contract_id}")
        if p.work_id is not None:
            if p.work_id not in work_contract:
                errors.append(f"payments.csv: платёж {p.payment_id}: неизвестная работа {p.work_id}")
            elif work_contract[p.work_id] != p.contract_id:
                # Молча "починить" нельзя: непонятно, ошибка в договоре или в работе.
                errors.append(
                    f"payments.csv: платёж {p.payment_id}: работа {p.work_id} относится к договору "
                    f"{work_contract[p.work_id]}, а платёж указан по договору {p.contract_id}"
                )

    if errors:
        raise DataError(errors)
    return Dataset(tuple(contracts), tuple(works), tuple(payments))


def _payment_dates_problem(p: Payment) -> Optional[str]:
    """Статус платежа должен соответствовать заполненным датам."""
    if p.status == "queued" and p.paid_at is not None:
        return "статус queued, но указана дата оплаты paid_at"
    if p.status == "paid" and p.paid_at is None:
        return "статус paid, но нет paid_at"
    if p.status == "refunded":
        if p.paid_at is None or p.refunded_at is None:
            return "статус refunded, но нет paid_at или refunded_at"
        if p.refunded_at < p.paid_at:
            return "возврат раньше оплаты (refunded_at < paid_at)"
    return None

